formulas.expression:
if(
AND({!$Record.AEHC_Is_Subscription__c}, ISPICKVAL({!$Record__Prior.Approval_Status__c}, 'Business Owner Publication Review'), {!$Record.AEHC_Subscription_Request__r.AEHC_UAT_Approval__c}),
' UAT Toggle Enabled ',''
)

AND(NOT({!Is_new}) , OR (Text({!$Record.Approval_Status__c}) == 'DDH Admin Review' ,
Text({!$Record.Approval_Status__c}) == 'Business Owner Publication Review' ,
Text({!$Record.Approval_Status__c}) == 'Submitted to DDH'
),
ISCHANGED({!$Record.Approval_Status__c})

)
